#!/usr/bin/env python3
"""Read linked ELF/SDK evidence only. Never connects to USB or executes target code."""
import pathlib,subprocess,struct,hashlib,json,argparse,sys
sys.dont_write_bytecode=True
from prepare_sources import ROOT,sha
p=argparse.ArgumentParser();p.add_argument('--build-root',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);p.add_argument('--reference-source',type=pathlib.Path,required=True);a=p.parse_args();assert not a.output.exists()
r=json.loads((a.build_root/'report.json').read_text());assert r['status']=='PASS';elf=a.build_root/'build/EvilDuckS3.ino.elf';assert sha(elf)==r['provenance']['elf_sha256'];core=pathlib.Path(r['provenance']['core']);sdk=core.parents[2]/'tools/esp32-arduino-libs/idf-release_v5.5-b66b5448-v1/esp32s3';prefix=str(pathlib.Path(r['link_command'][0])).rsplit('g++',1)[0]
raw=elf.read_bytes();lines=subprocess.check_output([prefix+'nm','-S','--defined-only',str(elf)],text=True).splitlines();row=next(l for l in lines if l.endswith(' _ZL17report_descriptor'));addr,size=[int(x,16) for x in row.split()[:2]];off=struct.unpack_from('<I',raw,32)[0];width,count=struct.unpack_from('<HH',raw,46)
for i in range(count):
 row=struct.unpack_from('<10I',raw,off+i*width);kind,flags,base,data,sz=row[1:6]
 if kind!=8 and flags&2 and base<=addr and addr+size<=base+sz:desc=raw[data+addr-base:data+addr-base+size];break
else:raise AssertionError('descriptor not in allocated ELF section')
expected=bytes.fromhex('05010906a1018501050719e029e715002501950875018102950175088101050819012905950575019102950175039101050719002aff00150026ff00950675088100c0');assert desc==expected
archive=sdk/'lib/libarduino_tinyusb.a';old=json.loads((ROOT/'docs/stage15-upstream-sources.json').read_text());assert sha(archive)==next(x['sha256'] for x in old['sources'] if x['path'].endswith('/libarduino_tinyusb.a'))
member='hid_device.c.obj';obj=a.output.parent/(a.output.stem+'-hid.tmp.o');obj.write_bytes(subprocess.check_output([prefix+'ar','p',str(archive),member]));dis=subprocess.check_output([prefix+'objdump','-dr',str(obj)],text=True);oh=sha(obj);obj.unlink();assert dis.count('tud_hid_set_report_cb')>=2
pin=json.loads((ROOT/'docs/stage28n-source-manifest.json').read_text());ref=next(x for x in pin['vendor_inputs'] if x['file']=='src/class/hid/hid_device.c');assert sha(a.reference_source)==ref['sha256']
inputs=[core/'libraries/USB/src/USBHID.cpp',core/'libraries/USB/src/USBHIDKeyboard.cpp',core/'cores/esp32/esp32-hal-tinyusb.c',sdk/'include/arduino_tinyusb/tinyusb/src/class/hid/hid_device.h',sdk/'include/arduino_tinyusb/tinyusb/src/device/usbd.h']
out=dict(status='PASS',elf_sha256=sha(elf),keyboard_report_descriptor=dict(bytes=size,hex=desc.hex(),sha256=hashlib.sha256(desc).hexdigest(),collection='Generic Desktop Keyboard Application',report_id=1,input_payload_bytes=8,output_payload_bytes=1,led_bits='Num,Caps,Scroll,Compose,Kana',constant_padding_bits=3),inputs=[dict(file=str(f),sha256=sha(f)) for f in inputs],sdk_archive_sha256=sha(archive),hid_object_sha256=oh,hid_object_disassembly=dis,reference_source=ref,source_to_shipped_object_rebuild_attested=False,hardware=False,interface_class=3,interface_subclass=0,interface_protocol=0,interface_evidence='First static USBHID HID constructor selects NONE before derived keyboard constructor. Runtime descriptor constructed later, not physically captured.',endpoints='HID interrupt IN and OUT, 64-byte endpoints, 1ms descriptor interval; endpoint numbers chosen dynamically from available allocator. No claim of actual host enumeration.',control_path='SET_REPORT SETUP accepts bounded length; ACK normalizes optional matching prefix then invokes callback.',interrupt_out_path='Successful OUT completion invokes same callback with id0/typeOUTPUT/full endpoint payload; failures use report_failed, then rearm.',raw_hook_limits='Only actual tud_hid_set_report_cb arrivals. Not early setup rejection, failed OUT transfers, controller/wire packets, descriptor exposure or host recognition.')
